1|// Session track selection. Pure: no env, no fetch, no audio.
2|import type {
3|  MusicConfig,
4|  MusicManifest,
5|  MusicSelection,
6|  PersistedMusicPrefs,
7|  Rng,
8|  SceneSignal,
9|  Track,
10|} from "./music-types";
11|import { compareTrackId, dominantEmotion, rankScored, rankTracks, resolveConfig } from "./music-similarity";
12|import type { RankedTrack } from "./music-similarity";
13|
14|// The one audible-scope filter: playlist-only tracks never enter emotion
15|// selection, so every scope below goes through here.
16|export function audibleTracks(manifest: MusicManifest): Track[] {
17|  return manifest.tracks.filter((t) => t.playlistOnly !== true);
18|}
19|
20|// Style scope for every pick. A null style means the whole audible set.
21|export function candidatesFor(selection: MusicSelection, manifest: MusicManifest): Track[] {
22|  const audible = audibleTracks(manifest);
23|  if (selection.style === null) return audible;
24|  return audible.filter((t) => t.style === selection.style);
25|}
26|
27|// Best match by score, ties to the lower id. A null scene takes the
28|// first track in id order. Skips one id (the ended track) when given.
29|export function bestRanked(
30|  scene: SceneSignal | null,
31|  tracks: Track[],
32|  excludeId?: string | null,
33|  override?: Partial<MusicConfig>,
34|): Track | null {
35|  const eligible =
36|    excludeId === null || excludeId === undefined
37|      ? tracks
38|      : tracks.filter((t) => t.id !== excludeId);
39|  if (eligible.length === 0) return null;
40|  if (scene === null) return [...eligible].sort(compareTrackId)[0] ?? null;
41|  return rankScored(scene, eligible, override)[0]?.track ?? null;
42|}
43|
44|// Next track: the next same-emotion track in score order across the whole
45|// style, wrapping and skipping the current. With no other same-emotion
46|// track, the best same-style track overall. A null scene cycles the style
47|// set in id order. One track or none gives null.
48|export function nextTrack(
49|  scene: SceneSignal | null,
50|  manifest: MusicManifest,
51|  currentTrackId: string | null,
52|  override?: Partial<MusicConfig>,
53|  selection?: MusicSelection | null,
54|): Track | null {
55|  const scope = candidatesFor(selection ?? { style: null }, manifest);
56|  if (scope.length <= 1) return null;
57|  const config = resolveConfig(override);
58|  const scoped = { ...manifest, tracks: scope };
59|  if (scene === null) {
60|    const ids = [...scope].sort(compareTrackId);
61|    const at = ids.findIndex((t) => t.id === currentTrackId);
62|    return ids[(at + 1) % ids.length] as Track;
63|  }
64|  const ranked = rankTracks(scene, scoped, config);
65|  const same = ranked.filter((t) => t.emotion === dominantEmotion(scene));
66|  const others = same.filter((t) => t.id !== currentTrackId);
67|  if (others.length > 0) {
68|    const at = same.findIndex((t) => t.id === currentTrackId);
69|    if (at >= 0) return same[(at + 1) % same.length] as Track;
70|    return same[0] as Track;
71|  }
72|  return ranked.find((t) => t.id !== currentTrackId) ?? null;
73|}
74|
75|export interface ScheduledDraw {
76|  cands: Track[];
77|  scene: SceneSignal | null;
78|  currentId: string | null;
79|  currentStartedSec: number;
80|  nowSec: number;
81|  rng: Rng;
82|  override?: Partial<MusicConfig>;
83|}
84|
85|// The one scheduled draw: same-style tracks with the scene's dominant
86|// emotion (or the whole style set when none matches), kept within
87|// randomTolerance of the best. The current track stays when eligible;
88|// otherwise the min-track hold keeps it until it played long enough,
89|// and the draw skips it when an alternative exists. One rng call per
90|// draw, only when a draw happens.
91|export function selectScheduled(draw: ScheduledDraw): Track | null {
92|  const { cands, scene, currentId, rng } = draw;
93|  if (cands.length === 0 || scene === null) return null;
94|  const config = resolveConfig(draw.override);
95|  const ranked = rankScored(scene, cands, config);
96|  const dom = dominantEmotion(scene);
97|  const pool = ranked.filter((entry) => entry.track.emotion === dom);
98|  const kept = pool.length > 0 ? pool : ranked;
99|  const best = kept[0]?.score ?? 0;
100|  const eligible = kept.filter((entry) => entry.score >= best - config.randomTolerance);
101|  const current = currentId !== null ? eligible.find((entry) => entry.track.id === currentId) : undefined;
102|  if (current) return current.track;
103|  if (currentId !== null && draw.nowSec - draw.currentStartedSec < config.minTrackSec) return null;
104|  const rest = eligible.filter((entry) => entry.track.id !== currentId);
105|  const drawFrom = rest.length > 0 ? rest : eligible;
106|  if (drawFrom.length === 0) return null;
107|  return (drawFrom[Math.floor(rng() * drawFrom.length)] as RankedTrack).track;
108|}
109|
110|// Random mode draw: the scheduled draw without the min-track hold, which
111|// only the scheduler owns. An infinite clock always passes the hold.
112|export function pickRandomTrack(
113|  cands: Track[],
114|  scene: SceneSignal | null,
115|  excludeId: string | null,
116|  rng: Rng,
117|  override?: Partial<MusicConfig>,
118|): Track | null {
119|  if (cands.length === 0) return null;
120|  if (scene === null) {
121|    const ids = [...cands].sort(compareTrackId);
122|    const at = ids.findIndex((t) => t.id === excludeId);
123|    return ids[(at + 1) % ids.length] as Track;
124|  }
125|  return selectScheduled({
126|    cands,
127|    scene,
128|    currentId: excludeId,
129|    currentStartedSec: 0,
130|    nowSec: Number.POSITIVE_INFINITY,
131|    rng,
132|    override,
133|  });
134|}
135|
136|// True when the style has at least one emotion-selectable track. The style
137|// selector uses this, so a style with only playlist tracks stays hidden.
138|export function styleHasTracks(manifest: MusicManifest, style: string): boolean {
139|  return audibleTracks(manifest).some((t) => t.style === style);
140|}
141|
142|// Session defaults on load. A stored style with no tracks falls back to
143|// the first style that has any.
144|export function resolveInitialSelection(
145|  manifest: MusicManifest,
146|  persisted: PersistedMusicPrefs | null,
147|): MusicSelection {
148|  const fallback = manifest.styles.find((s) => styleHasTracks(manifest, s.id))?.id ?? null;
149|  const style =
150|    persisted?.style !== null &&
151|    persisted?.style !== undefined &&
152|    styleHasTracks(manifest, persisted.style)
153|      ? persisted.style
154|      : fallback;
155|  return { style };
156|}
157|
158|// Style change from user action: the best match for the scene in the new
159|// style by score. Never crosses styles. Null when the style has no tracks.
160|export function requestStyleChange(
161|  manifest: MusicManifest,
162|  style: string,
163|  scene: SceneSignal | null,
164|  override?: Partial<MusicConfig>,
165|): { track: Track } | null {
166|  const scoped = audibleTracks(manifest).filter((t) => t.style === style);
167|  if (scoped.length === 0) return null;
168|  const track = bestRanked(scene, scoped, null, override);
169|  return track ? { track } : null;
170|}

