1|// Music session: the single policy owner behind the reader. Pure and
2|// React-free: no timers, no Date.now, no Math.random, no storage. The
3|// reader builds the context (clock, rng, scene signals) and bridges the
4|// view to React state. The player stays the mechanism that performs
5|// crossfades; this module decides them.
6|import {
7|  CHOPIN_PLAYLIST_ID,
8|  MUSIC_CONFIG,
9|  nextTrack,
10|  resolveInitialSelection,
11|} from "./music";
12|import type {
13|  MusicManifest,
14|  MusicSelection,
15|  PersistedMusicPrefs,
16|  Rng,
17|  SceneSignal,
18|} from "./music";
19|import {
20|  enterPlaylist,
21|  exitPlaylist,
22|  initScheduler,
23|  noteTrackEnded,
24|  observeScene,
25|  requestManualTrack,
26|  requestNext,
27|  switchStyle,
28|  tickScheduler,
29|} from "./music-schedule";
30|import type { ScheduleDecision, SchedulerState } from "./music-schedule";
31|import { popHistory, pushHistory } from "./music-history";
32|
33|export interface MusicSession {
34|  scheduler: SchedulerState;
35|  history: string[];
36|  selection: MusicSelection;
37|  fadeSec: number;
38|  replayNonce: number;
39|  view: SessionView;
40|}
41|
42|export interface SessionView {
43|  currentId: string | null;
44|  fadeSec: number;
45|  replayNonce: number;
46|  canPrev: boolean;
47|  canSkip: boolean;
48|  playlistOn: boolean;
49|  style: string | null;
50|}
51|
52|export interface SessionContext {
53|  manifest: MusicManifest;
54|  signalOf: (sceneId: string) => SceneSignal | null;
55|  routeSceneId: string | null;
56|  nowSec: number;
57|  rng: Rng;
58|}
59|
60|export type MusicIntent =
61|  | { type: "sceneEntered"; sceneId: string }
62|  | { type: "tick" }
63|  | { type: "skip" }
64|  | { type: "previous" }
65|  | { type: "styleChanged"; style: string }
66|  | { type: "trackEnded"; trackId: string }
67|  | { type: "playlistToggled" };
68|
69|// Route entries use the short dwell; the draw and the holds are unchanged.
70|const ENTRY_DWELL = { dwellSec: MUSIC_CONFIG.sceneEntryDwellSec };
71|
72|// The Chopin playlist, when the manifest defines it with tracks. The
73|// button stays hidden otherwise, and the player never persists the playlist.
74|export function findChopinPlaylist(manifest: MusicManifest) {
75|  const found = manifest.playlists.find((p) => p.id === CHOPIN_PLAYLIST_ID) ?? null;
76|  return found && found.trackIds.length > 0 ? found : null;
77|}
78|
79|export function startSession(
80|  manifest: MusicManifest,
81|  prefs: PersistedMusicPrefs | null,
82|): MusicSession {
83|  const fields = {
84|    scheduler: initScheduler(),
85|    history: [] as string[],
86|    selection: resolveInitialSelection(manifest, prefs),
87|    fadeSec: 0,
88|    replayNonce: 0,
89|  };
90|  return {
91|    ...fields,
92|    view: buildView(fields, manifest, null, fields.selection),
93|  };
94|}
95|
96|function sameScheduler(a: SchedulerState, b: SchedulerState): boolean {
97|  return (
98|    a.currentId === b.currentId &&
99|    a.currentStartedSec === b.currentStartedSec &&
100|    a.activeSceneId === b.activeSceneId &&
101|    a.pendingSceneId === b.pendingSceneId &&
102|    a.pendingSinceSec === b.pendingSinceSec &&
103|    a.overrideId === b.overrideId &&
104|    a.overrideSceneId === b.overrideSceneId &&
105|    (a.playlist === null || b.playlist === null
106|      ? a.playlist === b.playlist
107|      : a.playlist.id === b.playlist.id && a.playlist.index === b.playlist.index)
108|  );
109|}
110|
111|function viewEqual(a: SessionView, b: SessionView): boolean {
112|  return (
113|    a.currentId === b.currentId &&
114|    a.fadeSec === b.fadeSec &&
115|    a.replayNonce === b.replayNonce &&
116|    a.canPrev === b.canPrev &&
117|    a.canSkip === b.canSkip &&
118|    a.playlistOn === b.playlistOn &&
119|    a.style === b.style
120|  );
121|}
122|
123|function buildView(
124|  fields: Omit<MusicSession, "view">,
125|  manifest: MusicManifest,
126|  routeSignal: SceneSignal | null,
127|  selection: MusicSelection,
128|): SessionView {
129|  const currentId = fields.scheduler.currentId;
130|  const playlistOn = fields.scheduler.playlist !== null;
131|  const canSkip = playlistOn
132|    ? (findChopinPlaylist(manifest)?.trackIds.length ?? 0) > 1
133|    : manifest.tracks.length > 1 &&
134|      nextTrack(routeSignal, manifest, currentId, undefined, selection) !== null;
135|  return {
136|    currentId,
137|    fadeSec: fields.fadeSec,
138|    replayNonce: fields.replayNonce,
139|    canPrev: currentId !== null,
140|    canSkip,
141|    playlistOn,
142|    style: selection.style,
143|  };
144|}
145|
146|function routeSignalOf(ctx: SessionContext): SceneSignal | null {
147|  return ctx.routeSceneId !== null ? ctx.signalOf(ctx.routeSceneId) : null;
148|}
149|
150|// Rebuild the session after a handler ran, reusing the session and the
151|// view objects when nothing changed so the reader's 1 s tick rerenders
152|// nothing.
153|function settle(session: MusicSession, fields: Omit<MusicSession, "view">, ctx: SessionContext): MusicSession {
154|  const view = buildView(fields, ctx.manifest, routeSignalOf(ctx), fields.selection);
155|  if (
156|    sameScheduler(session.scheduler, fields.scheduler) &&
157|    session.history === fields.history &&
158|    session.selection === fields.selection &&
159|    session.fadeSec === fields.fadeSec &&
160|    session.replayNonce === fields.replayNonce &&
161|    viewEqual(session.view, view)
162|  ) {
163|    return session;
164|  }
165|  return { ...fields, view: viewEqual(session.view, view) ? session.view : view };
166|}
167|
168|// Fold a scheduler decision into the session: fade on every switch, a
169|// replay nonce bump on a same-id wrap, and the outgoing id banked for
170|// Previous on every automatic switch. Previous passes push false so it
171|// never re-banks.
172|function foldSwitch(
173|  base: Omit<MusicSession, "view">,
174|  decision: ScheduleDecision,
175|  push: boolean,
176|): Omit<MusicSession, "view"> {
177|  const prevId = base.scheduler.currentId;
178|  if (decision.switchToId === null) return { ...base, scheduler: decision.state };
179|  if (decision.switchToId === prevId) {
180|    return {
181|      ...base,
182|      scheduler: decision.state,
183|      fadeSec: decision.crossfadeSec,
184|      replayNonce: base.replayNonce + 1,
185|    };
186|  }
187|  return {
188|    ...base,
189|    scheduler: decision.state,
190|    history: push && prevId !== null ? pushHistory(base.history, prevId) : base.history,
191|    fadeSec: decision.crossfadeSec,
192|  };
193|}
194|
195|function baseOf(session: MusicSession): Omit<MusicSession, "view"> {
196|  return {
197|    scheduler: session.scheduler,
198|    history: session.history,
199|    selection: session.selection,
200|    fadeSec: session.fadeSec,
201|    replayNonce: session.replayNonce,
202|  };
203|}
204|
205|function selectEnv(session: MusicSession, ctx: SessionContext) {
206|  return { selection: session.selection, rng: ctx.rng };
207|}
208|
209|export function dispatch(session: MusicSession, intent: MusicIntent, ctx: SessionContext): MusicSession {
210|  switch (intent.type) {
211|    case "sceneEntered": {
212|      const signal = ctx.signalOf(intent.sceneId);
213|      const decision = observeScene(
214|        session.scheduler,
215|        intent.sceneId,
216|        signal,
217|        ctx.manifest,
218|        ctx.nowSec,
219|        selectEnv(session, ctx),
220|        ENTRY_DWELL,
221|      );
222|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
223|    }
224|    case "tick": {
225|      if (ctx.routeSceneId === null) return session;
226|      const sceneId = session.scheduler.pendingSceneId ?? ctx.routeSceneId;
227|      const decision = tickScheduler(
228|        session.scheduler,
229|        ctx.signalOf(sceneId),
230|        ctx.manifest,
231|        ctx.nowSec,
232|        selectEnv(session, ctx),
233|        ENTRY_DWELL,
234|      );
235|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
236|    }
237|    case "skip": {
238|      if (ctx.routeSceneId === null) return session;
239|      const decision = requestNext(
240|        session.scheduler,
241|        ctx.signalOf(ctx.routeSceneId),
242|        ctx.manifest,
243|        ctx.nowSec,
244|        selectEnv(session, ctx),
245|      );
246|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
247|    }
248|    case "previous": {
249|      if (session.scheduler.playlist !== null) {
250|        return settle(session, { ...baseOf(session), replayNonce: session.replayNonce + 1 }, ctx);
251|      }
252|      const popped = popHistory(session.history);
253|      if (!popped) {
254|        return settle(session, { ...baseOf(session), replayNonce: session.replayNonce + 1 }, ctx);
255|      }
256|      const base = { ...baseOf(session), history: popped.hist };
257|      const decision = requestManualTrack(session.scheduler, ctx.manifest, popped.id, ctx.nowSec);
258|      return settle(session, foldSwitch(base, decision, false), ctx);
259|    }
260|    case "styleChanged": {
261|      if (ctx.routeSceneId === null) return session;
262|      if (session.scheduler.playlist !== null) return session;
263|      if (intent.style === session.selection.style) return session;
264|      const decision = switchStyle(
265|        session.scheduler,
266|        ctx.signalOf(ctx.routeSceneId),
267|        ctx.manifest,
268|        ctx.nowSec,
269|        intent.style,
270|      );
271|      if (decision.switchToId === null) return session;
272|      const fields = foldSwitch(baseOf(session), decision, true);
273|      return settle(session, { ...fields, selection: { style: intent.style } }, ctx);
274|    }
275|    case "trackEnded": {
276|      if (ctx.routeSceneId === null) return session;
277|      const decision = noteTrackEnded(
278|        session.scheduler,
279|        ctx.signalOf(ctx.routeSceneId),
280|        ctx.manifest,
281|        intent.trackId,
282|        ctx.nowSec,
283|        selectEnv(session, ctx),
284|      );
285|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
286|    }
287|    case "playlistToggled": {
288|      const playlist = findChopinPlaylist(ctx.manifest);
289|      if (!playlist) return session;
290|      if (session.scheduler.playlist !== null) {
291|        const signal = ctx.routeSceneId !== null ? ctx.signalOf(ctx.routeSceneId) : null;
292|        const decision = exitPlaylist(
293|          session.scheduler,
294|          signal,
295|          ctx.manifest,
296|          ctx.nowSec,
297|          selectEnv(session, ctx),
298|        );
299|        return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
300|      }
301|      const decision = enterPlaylist(session.scheduler, ctx.manifest, playlist.id, ctx.nowSec);
302|      return settle(session, foldSwitch(baseOf(session), decision, true), ctx);
303|    }
304|    default: {
305|      const _exhaustive: never = intent;
306|      throw new Error(`unknown music intent: ${JSON.stringify(_exhaustive)}`);
307|    }
308|  }
309|}

