1|// Pure music scheduler. The reader calls it with explicit nowSec values,
2|// so dwell and the min-track hold are testable without timers.
3|import {
4|  MUSIC_CONFIG,
5|  bestRanked,
6|  candidatesFor,
7|  nextTrack,
8|  requestStyleChange,
9|  resolveConfig,
10|  selectScheduled,
11|} from "./music";
12|import type { MusicConfig, MusicManifest, SceneSignal, SelectEnv } from "./music";
13|
14|export interface SchedulerState {
15|  currentId: string | null;
16|  currentStartedSec: number;
17|  activeSceneId: string | null;
18|  pendingSceneId: string | null;
19|  pendingSinceSec: number;
20|  overrideId: string | null;
21|  overrideSceneId: string | null;
22|  playlist: { id: string; index: number } | null;
23|}
24|
25|export interface ScheduleDecision {
26|  state: SchedulerState;
27|  switchToId: string | null;
28|  crossfadeSec: number;
29|}
30|
31|export function initScheduler(): SchedulerState {
32|  return {
33|    currentId: null,
34|    currentStartedSec: 0,
35|    activeSceneId: null,
36|    pendingSceneId: null,
37|    pendingSinceSec: 0,
38|    overrideId: null,
39|    overrideSceneId: null,
40|    playlist: null,
41|  };
42|}
43|
44|function noChange(state: SchedulerState): ScheduleDecision {
45|  return { state, switchToId: null, crossfadeSec: 0 };
46|}
47|
48|// Scheduled select: the one draw from the selection module keeps the
49|// current track when it is eligible, so rescans do not churn. Dwell is
50|// handled by promotion; the draw itself holds the min-track pick.
51|function evaluateSwitch(
52|  state: SchedulerState,
53|  signal: SceneSignal | null,
54|  manifest: MusicManifest,
55|  nowSec: number,
56|  config: MusicConfig,
57|  env: SelectEnv,
58|): ScheduleDecision {
59|  if (signal === null) return noChange(state);
60|  if (state.playlist !== null) return noChange(state);
61|  const styleTracks = candidatesFor(env.selection, manifest);
62|  if (styleTracks.length === 0) return noChange(state);
63|  const pick = selectScheduled({
64|    cands: styleTracks,
65|    scene: signal,
66|    currentId: state.currentId,
67|    currentStartedSec: state.currentStartedSec,
68|    nowSec,
69|    rng: env.rng,
70|    override: config,
71|  });
72|  if (!pick || pick.id === state.currentId) return noChange(state);
73|  return {
74|    state: { ...state, currentId: pick.id, currentStartedSec: nowSec },
75|    switchToId: pick.id,
76|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
77|  };
78|}
79|
80|function promote(
81|  state: SchedulerState,
82|  sceneId: string,
83|  signal: SceneSignal | null,
84|  manifest: MusicManifest,
85|  nowSec: number,
86|  config: MusicConfig,
87|  env: SelectEnv,
88|): ScheduleDecision {
89|  const settled: SchedulerState = {
90|    ...state,
91|    activeSceneId: sceneId,
92|    pendingSceneId: null,
93|    pendingSinceSec: 0,
94|    overrideId: null,
95|    overrideSceneId: null,
96|  };
97|  const decision = evaluateSwitch(settled, signal, manifest, nowSec, config, env);
98|  return { ...decision, state: { ...decision.state, activeSceneId: sceneId } };
99|}
100|
101|// The reading position entered a scene. It becomes pending and the dwell
102|// clock restarts, so fast scrolling keeps only the newest scene. After
103|// the pending scene holds for dwellSec it becomes active. The first
104|// track ever plays at once, with no dwell.
105|export function observeScene(
106|  state: SchedulerState,
107|  sceneId: string,
108|  signal: SceneSignal | null,
109|  manifest: MusicManifest,
110|  nowSec: number,
111|  env: SelectEnv,
112|  override?: Partial<MusicConfig>,
113|): ScheduleDecision {
114|  const config = resolveConfig(override ?? MUSIC_CONFIG);
115|  if (state.currentId === null) {
116|    return promote(state, sceneId, signal, manifest, nowSec, config, env);
117|  }
118|  if (sceneId === state.activeSceneId) {
119|    return noChange({ ...state, pendingSceneId: null, pendingSinceSec: 0 });
120|  }
121|  if (sceneId !== state.pendingSceneId) {
122|    return noChange({ ...state, pendingSceneId: sceneId, pendingSinceSec: nowSec });
123|  }
124|  if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
125|  return promote(state, sceneId, signal, manifest, nowSec, config, env);
126|}
127|
128|// Time passed: settle a pending scene whose dwell has expired, or
129|// re-check the active scene (a hold from minTrackSec may have expired).
130|// The reader passes the pending signal when one exists, else the active.
131|export function tickScheduler(
132|  state: SchedulerState,
133|  signal: SceneSignal | null,
134|  manifest: MusicManifest,
135|  nowSec: number,
136|  env: SelectEnv,
137|  override?: Partial<MusicConfig>,
138|): ScheduleDecision {
139|  const config = resolveConfig(override ?? MUSIC_CONFIG);
140|  if (state.currentId === null) return noChange(state);
141|  if (state.pendingSceneId !== null) {
142|    if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
143|    return promote(state, state.pendingSceneId, signal, manifest, nowSec, config, env);
144|  }
145|  // A skip override holds until the next scene change; promotion clears it.
146|  if (state.overrideId !== null) return noChange(state);
147|  if (state.activeSceneId === null) return noChange(state);
148|  return evaluateSwitch(state, signal, manifest, nowSec, config, env);
149|}
150|
151|// Reader skip: the same-emotion Next rule, applied at once with the
152|// normal crossfade. The choice holds until the next scene change.
153|export function requestNext(
154|  state: SchedulerState,
155|  signal: SceneSignal | null,
156|  manifest: MusicManifest,
157|  nowSec: number,
158|  env: SelectEnv,
159|  override?: Partial<MusicConfig>,
160|): ScheduleDecision {
161|  const config = resolveConfig(override ?? MUSIC_CONFIG);
162|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
163|  const next = nextTrack(signal, manifest, state.currentId, config, env.selection);
164|  if (!next) return noChange(state);
165|  return {
166|    state: {
167|      ...state,
168|      currentId: next.id,
169|      currentStartedSec: nowSec,
170|      overrideId: next.id,
171|      overrideSceneId: state.activeSceneId,
172|    },
173|    switchToId: next.id,
174|    crossfadeSec: config.crossfadeSec,
175|  };
176|}
177|
178|// Manual pick from Previous: the track holds like a Next until the next
179|// scene change. Unknown ids change nothing.
180|export function requestManualTrack(
181|  state: SchedulerState,
182|  manifest: MusicManifest,
183|  trackId: string,
184|  nowSec: number,
185|  override?: Partial<MusicConfig>,
186|): ScheduleDecision {
187|  const config = resolveConfig(override ?? MUSIC_CONFIG);
188|  if (state.playlist !== null) return noChange(state);
189|  const picked = manifest.tracks.find((t) => t.id === trackId) ?? null;
190|  if (!picked) return noChange(state);
191|  return {
192|    state: {
193|      ...state,
194|      currentId: picked.id,
195|      currentStartedSec: nowSec,
196|      overrideId: picked.id,
197|      overrideSceneId: state.activeSceneId,
198|    },
199|    switchToId: picked.id,
200|    crossfadeSec: config.crossfadeSec,
201|  };
202|}
203|
204|// A non-looping track ended: fade into the best remaining track,
205|// excluding the one that just ended. Never crosses styles.
206|export function noteTrackEnded(
207|  state: SchedulerState,
208|  signal: SceneSignal | null,
209|  manifest: MusicManifest,
210|  endedId: string,
211|  nowSec: number,
212|  env: SelectEnv,
213|  override?: Partial<MusicConfig>,
214|): ScheduleDecision {
215|  const config = resolveConfig(override ?? MUSIC_CONFIG);
216|  if (state.playlist !== null) return advancePlaylist(state, manifest, nowSec, config);
217|  const styleTracks = candidatesFor(env.selection, manifest);
218|  if (styleTracks.length === 0) return noChange(state);
219|  const best = bestRanked(signal, styleTracks, endedId, config);
220|  if (!best) return noChange(state);
221|  return {
222|    state: {
223|      ...state,
224|      currentId: best.id,
225|      currentStartedSec: nowSec,
226|      overrideId: null,
227|      overrideSceneId: null,
228|    },
229|    switchToId: best.id,
230|    crossfadeSec: config.crossfadeSec,
231|  };
232|}
233|
234|// Fixed playlist mode (the Chopin easter egg). Playlist order lives here
235|// because it reuses SchedulerState and the crossfade config.
236|function playlistById(manifest: MusicManifest, id: string) {
237|  return manifest.playlists.find((p) => p.id === id) ?? null;
238|}
239|
240|// Enter playlist mode: switch at once to the first track, with no dwell
241|// and no min-track rule. Scene changes stay tracked but never switch.
242|export function enterPlaylist(
243|  state: SchedulerState,
244|  manifest: MusicManifest,
245|  playlistId: string,
246|  nowSec: number,
247|  override?: Partial<MusicConfig>,
248|): ScheduleDecision {
249|  const config = resolveConfig(override ?? MUSIC_CONFIG);
250|  const playlist = playlistById(manifest, playlistId);
251|  const firstId = playlist?.trackIds[0];
252|  const first = firstId ? (manifest.tracks.find((t) => t.id === firstId) ?? null) : null;
253|  if (!playlist || !first) return noChange(state);
254|  return {
255|    state: {
256|      ...state,
257|      currentId: first.id,
258|      currentStartedSec: nowSec,
259|      overrideId: null,
260|      overrideSceneId: null,
261|      playlist: { id: playlist.id, index: 0 },
262|    },
263|    switchToId: first.id,
264|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
265|  };
266|}
267|
268|// Next playlist track in trackIds order, wrapping last to first. Used by
269|// both the end-of-track path and the Next button while the playlist is on.
270|function advancePlaylist(
271|  state: SchedulerState,
272|  manifest: MusicManifest,
273|  nowSec: number,
274|  config: MusicConfig,
275|): ScheduleDecision {
276|  if (state.playlist === null) return noChange(state);
277|  const playlist = playlistById(manifest, state.playlist.id);
278|  if (!playlist || playlist.trackIds.length === 0) return noChange(state);
279|  // A one-track playlist wraps onto the same id. That still returns a
