49|// current track when it is eligible, so rescans do not churn. Dwell is
50|// handled by promotion; the draw itself holds the min-track pick.
51|function evaluateSwitch(
52|  state: SchedulerState,
53|  signal: SceneSignal | null,
54|  manifest: MusicManifest,
55|  nowSec: number,
56|  config: MusicConfig,
57|  env: SelectEnv,
58|): ScheduleDecision {
59|  if (signal === null) return noChange(state);
60|  if (state.playlist !== null) return noChange(state);
61|  const styleTracks = candidatesFor(env.selection, manifest);
62|  if (styleTracks.length === 0) return noChange(state);
63|  const pick = selectScheduled({
64|    cands: styleTracks,
65|    scene: signal,
66|    currentId: state.currentId,
67|    currentStartedSec: state.currentStartedSec,
68|    nowSec,
69|    rng: env.rng,
70|    override: config,
