80|function promote(
81|  state: SchedulerState,
82|  sceneId: string,
83|  signal: SceneSignal | null,
84|  manifest: MusicManifest,
85|  nowSec: number,
86|  config: MusicConfig,
87|  env: SelectEnv,
88|): ScheduleDecision {
89|  const settled: SchedulerState = {
90|    ...state,
91|    activeSceneId: sceneId,
92|    pendingSceneId: null,
93|    pendingSinceSec: 0,
94|    overrideId: null,
95|    overrideSceneId: null,
96|  };
97|  const decision = evaluateSwitch(settled, signal, manifest, nowSec, config, env);
98|  return { ...decision, state: { ...decision.state, activeSceneId: sceneId } };
