101|// The reading position entered a scene. It becomes pending and the dwell
102|// clock restarts, so fast scrolling keeps only the newest scene. After
103|// the pending scene holds for dwellSec it becomes active. The first
104|// track ever plays at once, with no dwell.
105|export function observeScene(
106|  state: SchedulerState,
107|  sceneId: string,
108|  signal: SceneSignal | null,
109|  manifest: MusicManifest,
110|  nowSec: number,
111|  env: SelectEnv,
112|  override?: Partial<MusicConfig>,
113|): ScheduleDecision {
114|  const config = resolveConfig(override ?? MUSIC_CONFIG);
115|  if (state.currentId === null) {
116|    return promote(state, sceneId, signal, manifest, nowSec, config, env);
117|  }
118|  if (sceneId === state.activeSceneId) {
119|    return noChange({ ...state, pendingSceneId: null, pendingSinceSec: 0 });
120|  }
121|  if (sceneId !== state.pendingSceneId) {
122|    return noChange({ ...state, pendingSceneId: sceneId, pendingSinceSec: nowSec });
123|  }
124|  if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
125|  return promote(state, sceneId, signal, manifest, nowSec, config, env);
