128|// Time passed: settle a pending scene whose dwell has expired, or
129|// re-check the active scene (a hold from minTrackSec may have expired).
130|// The reader passes the pending signal when one exists, else the active.
131|export function tickScheduler(
132|  state: SchedulerState,
133|  signal: SceneSignal | null,
134|  manifest: MusicManifest,
135|  nowSec: number,
136|  env: SelectEnv,
137|  override?: Partial<MusicConfig>,
138|): ScheduleDecision {
139|  const config = resolveConfig(override ?? MUSIC_CONFIG);
140|  if (state.currentId === null) return noChange(state);
141|  if (state.pendingSceneId !== null) {
142|    if (nowSec - state.pendingSinceSec < config.dwellSec) return noChange(state);
143|    return promote(state, state.pendingSceneId, signal, manifest, nowSec, config, env);
144|  }
145|  // A skip override holds until the next scene change; promotion clears it.
146|  if (state.overrideId !== null) return noChange(state);
147|  if (state.activeSceneId === null) return noChange(state);
148|  return evaluateSwitch(state, signal, manifest, nowSec, config, env);
