240|// Enter playlist mode: switch at once to the first track, with no dwell
241|// and no min-track rule. Scene changes stay tracked but never switch.
242|export function enterPlaylist(
243|  state: SchedulerState,
244|  manifest: MusicManifest,
245|  playlistId: string,
246|  nowSec: number,
247|  override?: Partial<MusicConfig>,
248|): ScheduleDecision {
249|  const config = resolveConfig(override ?? MUSIC_CONFIG);
250|  const playlist = playlistById(manifest, playlistId);
251|  const firstId = playlist?.trackIds[0];
252|  const first = firstId ? (manifest.tracks.find((t) => t.id === firstId) ?? null) : null;
253|  if (!playlist || !first) return noChange(state);
254|  return {
255|    state: {
256|      ...state,
257|      currentId: first.id,
258|      currentStartedSec: nowSec,
259|      overrideId: null,
260|      overrideSceneId: null,
261|      playlist: { id: playlist.id, index: 0 },
262|    },
263|    switchToId: first.id,
264|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
265|  };
