268|// Next playlist track in trackIds order, wrapping last to first. Used by
269|// both the end-of-track path and the Next button while the playlist is on.
270|function advancePlaylist(
271|  state: SchedulerState,
272|  manifest: MusicManifest,
273|  nowSec: number,
274|  config: MusicConfig,
275|): ScheduleDecision {
276|  if (state.playlist === null) return noChange(state);
277|  const playlist = playlistById(manifest, state.playlist.id);
278|  if (!playlist || playlist.trackIds.length === 0) return noChange(state);
279|  // A one-track playlist wraps onto the same id. That still returns a
280|  // switch so the ended element re-cues instead of going quiet.
281|  const nextIndex = (state.playlist.index + 1) % playlist.trackIds.length;
282|  const nextId = playlist.trackIds[nextIndex];
283|  if (nextId === undefined) return noChange(state);
284|  const next = manifest.tracks.find((t) => t.id === nextId) ?? null;
285|  if (!next) return noChange(state);
286|  return {
287|    state: {
288|      ...state,
289|      currentId: next.id,
290|      currentStartedSec: nowSec,
291|      overrideId: null,
292|      overrideSceneId: null,
293|      playlist: { id: playlist.id, index: nextIndex },
294|    },
295|    switchToId: next.id,
296|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
297|  };
