300|// Leave playlist mode: clear the playlist state and switch at once to the
301|// best match for the current scene under the restored selection.
302|export function exitPlaylist(
303|  state: SchedulerState,
304|  signal: SceneSignal | null,
305|  manifest: MusicManifest,
306|  nowSec: number,
307|  env: SelectEnv,
308|  override?: Partial<MusicConfig>,
309|): ScheduleDecision {
310|  if (state.playlist === null) return noChange(state);
311|  const config = resolveConfig(override ?? MUSIC_CONFIG);
312|  const styleTracks = candidatesFor(env.selection, manifest);
313|  const cleared: SchedulerState = {
314|    ...state,
315|    overrideId: null,
316|    overrideSceneId: null,
317|    playlist: null,
318|  };
319|  const best = bestRanked(signal, styleTracks, null, config);
320|  if (!best) return { ...noChange(cleared), state: cleared };
321|  return {
322|    state: { ...cleared, currentId: best.id, currentStartedSec: nowSec },
323|    switchToId: best.id,
324|    crossfadeSec: state.currentId === null ? 0 : config.crossfadeSec,
325|  };
